// PawNail has ONE logo: the neon "B" (public/logo_b.jpg, never edited). Owner decision 2026-11-07: the Shiba
// mascot is retired from every surface (chrome, auth, landing, footer, offline, official account, splash).
// Small derivatives are generated by scripts/brand/export_brand.py so no surface downloads the 175 KB original.
import { isPlaceholderAvatar } from "@/lib/avatar";

export const BRAND_LOGO = {
  /** default src (128 px covers 28-64 px chrome at DPR 2) */
  src: "/brand/logo-b-128.webp",
  srcSet: "/brand/logo-b-64.webp 64w, /brand/logo-b-128.webp 128w, /brand/logo-b-256.webp 256w",
  /** 512 px JPEG for metadata / anything that cannot take WebP */
  jpg: "/brand/logo-b-512.jpg",
} as const;

/** Avatar of the official PawNail account (production rows already store this path; the file is the B logo). */
export const OFFICIAL_AVATAR = "/brand/pawnail-official.jpg";

/** Official account avatar: an uploaded photo wins; empty / placeholder / legacy mascot URLs show the B logo. */
export function officialAvatarUrl(url?: string | null): string {
  if (isPlaceholderAvatar(url)) return OFFICIAL_AVATAR; // includes the retired mascot URL (lib/avatar.ts)
  return url as string;
}
